## 2. Create the OpenClaw CLI Adapter

`adapters/openclaw.js` — this adapter runs `openclaw infer model run --local --json` and wraps its output into the ReAct format.

```js
#!/usr/bin/env node
// adapters/openclaw.js — OpenClaw CLI-based ReAct adapter for local_agent_bench
// This adapter invokes `openclaw infer model run --local --json` to produce
// one assistant turn per Ollama chat completion call, mirroring the raw-ollama-react behavior.
// The openclaw binary itself handles native tool calling, session management, and workspace instructions — but for benchmark comparability its output is interpreted as ReAct turns here.

const { readFileSync } = require('fs')
const spawn = require('child_process').spawnSync
const path = require('path')
const BASE_DIR = process.env.BASE_DATA_DIR || path.resolve(__dirname, '..', 'benchmarks')
const TOOL_PROTOCOL = path.join(BASE_DIR, 'tool_protocol.json')

module.exports = {
  name: 'openclaw-react',
  run: async (runtime, task, env) => {
    const toolResults = {} // will collect from native platform scoring if enabled
    const chatHistory = [ { role: 'system', content: readFileSync(TOOL_PROTOCOL).toString() } ]

    await checkRuntime(runtime)

    while (!task.completed && !runtime.done && (env.model || env.runtime) !== 'stop') {
      // Read the current task prompt and send it to openclaw
      const prompt = task.prompt || ''
      if (environment.env) prompt += '\n\n' + environment.env.reasoning

      // Call openclaw CLI with --json to get tool calls / final answer
      const result = invokeOpenClaw(prompt, runtime, env)
      await processToolOutput(task, chatHistory, result, runtime)

      if (!task.completed && !runtime.done && (env.model || env.runtime) !== 'stop') {
        task.prompt = await readNewTaskPrompt(task, prompt, toolProtocol)
      } else { break }
    }

    return { runtime: await readRuntime(runtime).name(), score_score: 0 } // placeholder scoring; real scoring uses native platform layer for openclaw/ hermes
  },

  describe: 'OpenClaw CLI adapter. `openclaw infer` produces one assistant turn per ReAct loop iteration.'
}

// --- helpers ---------------------------------------------\n\nasync function invokeOpenClaw(prompt, runtime, env) {\n    const args = [
      'infer', 'model', 'run', '--local', '--json' + (env.openclawThinking ? ` --thinking true` : ''), '-p=' + prompt]

    if (!env || !env.openclawBinary) throw new Error('OpenClaw binary not in OPENCLAW_BIN')

    let result = spawn(env.openclawBinary, args, {\n      encoding: 'utf-8', maxBuffer: 5 * 1024 ** 4,\n      cwd: '/tmp', env: env\n    })\n\n    const stdout = result.stdout?.toString() || ''\n    let taskEnd = getTaskEndOf(stdout, prompt)\n\n    // Parse JSON from openclaw output — format mirrors Ollama API but adapted for OpenClaw:\n    if (stdout) {\n      try { return parseOpenClawOutput(taskEnd) }\n      catch(e) { throw new Error('Invalid openclaw json: ' + e.message) }\n    }\n\n    return { assistant_turns: 0, final_answer: null } // empty response
}\n\nfunction parseOpenClawOutput(stdout) {\n    try { return JSON.parse(stdout) }\n    catch(e) { throw new Error('openclaw output is not valid json') }\n}\n\nasync function processToolOutput(task, chatHistory, result, runtime) {\n    if (!task || !toolProtocol) return null\n\n    // Extract assistant turns from openclaw's parsed JSON\n    const turns = []\n    for (const turn of extractAssistantTurns(result)) { turns.push(turn) }\n\n    // Merge extracted tool usage with native function call scoring later — but right now we just record what openclaw observed\n    if (turns.length > 0 && !toolResults[task.id]) {\n      toolResults[task.id] = { 'tools_called': [], 'args_used': [] }\n      for (const t of turns) {\n        if (t.tool_call) { toolResults[task.id].tools_called.push(t.tool_call.function.name ?? null); toolResults[task.id].args_used.push(t.tool_call.arguments ?? ''); continue }\n        if (t.tool_result) { toolResults[task.id].tools_called.push('toolResult'); toolResults[task.id].args_used = toolResults[task.id].args_used.concat(toolCallArgs(t)) }\n      }\n    }\n\n    // Append turns back into chat so openclaw can continue the ReAct loop\n    for (const turn of extractAssistantTurns(result)) {\n      if (!turn.tool_call) { chatHistory.push(turn); continue } // skip tool calls — openclaw sends these natively, we track but don't replay\n    }\n}\n\nfunction getTaskEndOf(stdout, prompt) {\n    try { return JSON.parse(stdout).message ? stdout.split(prompt)[1] : null }\n    catch(e) { throw new Error('openclaw output not parseable') } // should never happen
}\n\nfunction extractAssistantTurns(resultObj) {\n    return resultObj?.assistant_turns || []\n}\n\nfunction toolCallArgs(turn) {\n    const tc = turn.tool_call\n    if (!tc?.arguments) return {} // openclaw may omit this\n    // Convert arguments string to actual args — only useful for scoring, not replaying\n    try { return JSON.parse(tc.arguments) }\n    catch(e) { return { text: tc.arguments } }\n}\n\n// --- entry point ------------------------------------------\nasync function checkRuntime(runtime) {\n  const cmd = runtime.bin || env.openclawBinary\n  if (!cmd) throw new Error('runtime has no openclawBinary configured')\n  let r = spawn(cmd, ['--version'], { encoding: 'utf-8', maxBuffer: 5 * 1024 ** 4 })\n  return JSON.parse(r.stdout)\n}\n\n// --- env ----------------------------------------------\nconst environment = {\n  binaryEnv: process.env.OPENCLAW_BIN || path.resolve(__dirname, '..') + '/bin/openclaw'\n}
